create temp table if not exists polat_experiment_cases(n integer primary key,b jsonb);
create or replace function pg_temp.bridge_id(n integer,k text)returns uuid language sql immutable as $$select ('91cb'||k||'-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create or replace function pg_temp.bridge_setup(n integer,maximum_value integer default 3,spend_value text default '0.06',timeout_value integer default 10000)returns void language plpgsql as $$declare b jsonb;begin
 insert into public.tenants(id,name,slug)values(pg_temp.bridge_id(n,'1000'),'Offline experiment fixture','polat-sandbox-experiment-'||n);
 b:=jsonb_build_object('version',1,'mode','OFFLINE_SYNTHETIC','provider','anthropic','model','claude-haiku-5-5','model_version','claude-haiku-5-5','protocol_version','2023-06-01','repository_sha',repeat('a',40),'corpus_version','polat-multiturn-v2','corpus_hash',repeat('b',64),'plan_hash',repeat('c',64),'manifest_hash',repeat('d',64),'authorization_record_hash',private.fse_hash('fixture-authorization-'||n),'account_scope_hash',private.fse_hash('fixture-account-'||n),'profile_version','polat-ai-fixture-v2','maximum_requests',maximum_value,'maximum_spend',spend_value,'maximum_attempt_liability','0.02','currency','USD','maximum_output_tokens',512,'timeout_ms',timeout_value,'targets',(select jsonb_agg(private.fse_hash('target-'||n||'-'||s)order by s)from generate_series(1,greatest(maximum_value,3))s),'expires_at',to_char((clock_timestamp()+interval '20 minutes')at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'financial_authority','NONE','live_operations_authorized',false,'authorized_external_requests',0,'execution_enabled',false);
 insert into polat_experiment_cases values(n,b);
 perform private.polat_experiment_prepare_fixture(pg_temp.bridge_id(n,'1000'),pg_temp.bridge_id(n,'2000'),b::text);
end;$$;
create or replace function pg_temp.bridge_reserve(n integer,s integer default 1)returns jsonb language sql as $$
 select private.polat_experiment_reserve_fixture(pg_temp.bridge_id(n,'1000'),pg_temp.bridge_id(n,'2000'),pg_temp.bridge_id(n*100+s,'3000'),b->'targets'->>(s-1),private.fse_hash('request-'||n||'-'||s),private.fse_hash('body-'||n||'-'||s),private.fse_hash(private.fse_canonical(b)))from polat_experiment_cases where polat_experiment_cases.n=$1
$$;
create or replace function pg_temp.bridge_begin(n integer,s integer default 1)returns jsonb language sql as $$
 select private.polat_experiment_begin_fixture(pg_temp.bridge_id(n,'1000'),pg_temp.bridge_id(n,'2000'),pg_temp.bridge_id(n*100+s,'3000'),private.fse_hash(private.fse_canonical(b)),pg_temp.bridge_id(n*100+s,'4000'),pg_temp.bridge_id(n,'6000'))from polat_experiment_cases where polat_experiment_cases.n=$1
$$;
create or replace function pg_temp.bridge_outcome(n integer,s integer default 1,kind text default 'PROVIDER_RESULT',status_value text default 'SUCCEEDED',qa_value text default 'APPROVED')returns jsonb language sql as $$
 select jsonb_build_object('version',1,'evidence_id',pg_temp.bridge_id(n*100+s+case kind when 'RESULT_UNKNOWN'then 20 when 'DELAYED_RESULT'then 30 when 'RECONCILIATION'then 40 when 'RUN_CANCELLED'then 50 else 0 end,'5000'),'stage',kind,'status',status_value,'response_hash',case when kind not in('RESULT_UNKNOWN','RUN_CANCELLED')then private.fse_hash('response-'||n||'-'||s)end,'response_identity_hash',case when kind not in('RESULT_UNKNOWN','RUN_CANCELLED')then private.fse_hash('msg-fixture-'||n||'-'||s)end,'elapsed_ms','1.000001','input_tokens',case when kind='RESULT_UNKNOWN'then null else 37 end,'output_tokens',case when kind='RESULT_UNKNOWN'then null else 121 end,'qa',qa_value,'reconciliation_hash',case when kind='RECONCILIATION'then private.fse_hash('independent-fixture-billing-'||n||'-'||s)end,'simulated_billed_amount',case when kind='RECONCILIATION'and status_value='SIMULATED_RECONCILED'then '0.01'end,'currency','USD','actual_billed_amount',null,'actual_billed_currency',null,'financial_authority','NONE','live_operations_authorized',false)
$$;
create or replace function pg_temp.bridge_record(n integer,s integer default 1,kind text default 'PROVIDER_RESULT',status_value text default 'SUCCEEDED',qa_value text default 'APPROVED')returns jsonb language sql as $$
 select private.polat_experiment_record_fixture(pg_temp.bridge_id(n,'1000'),pg_temp.bridge_id(n,'2000'),pg_temp.bridge_id(n*100+s,'3000'),private.fse_hash(private.fse_canonical(b)),pg_temp.bridge_id(n*100+s,'4000'),pg_temp.bridge_outcome(n,s,kind,status_value,qa_value)::text)from polat_experiment_cases where polat_experiment_cases.n=$1
$$;
